/* Koodo Reader PWA service worker.
 * Generated by scripts/build.mjs: VERSION, PWA_SCOPE_PREFIX and
 * PRECACHE_URLS below are substituted at build time.
 *
 * Strategy:
 *  - Precache: app shell (index.html + built static assets + startup-loaded
 *    public assets + the lib scripts index.html references), named per
 *    content revision. On install, unchanged content-hashed ./static/*
 *    files are copied forward from previous revisions instead of being
 *    re-downloaded. Every other entry is fetched strictly (one retry, then
 *    the install is discarded and the previous SW keeps serving).
 *  - Runtime: ONE unversioned cache ("koodo-runtime") with an
 *    x-koodo-cached-at stamp and count-based trimming, so redeploys never
 *    force users to re-fetch ~10 MB of on-demand assets.
 *  - Mutable ./lib/** assets (pdf.js API+worker, wasm, cmaps, tesseract:
 *    stable URLs whose BYTES change when upstream bumps a vendored lib) are
 *    network-first with a cache fallback. Serving them cache-first would
 *    pair a freshly precached pdf.mjs with a stale cached worker and hard-
 *    fail every PDF with an API/Worker version mismatch.
 *  - Cache lookups are ordered: current precache -> runtime -> older
 *    generations. Plain caches.match() searches in cache-creation order and
 *    would return the OLDEST generation's copy of a same-URL asset.
 *  - Updates: skipWaiting + clientsClaim; index.html reloads clients on
 *    controllerchange. Activate keeps exactly ONE superseded precache
 *    generation (caches.keys() is insertion-ordered) so tabs from the
 *    previous deploy keep resolving their old hashed URLs, and deletes
 *    older generations synchronously - a setTimeout purge dies with the
 *    idle-terminated SW (~30s) and leaves stale generations shadowing for
 *    a whole week.
 *  - Navigation fallback: cached index.html, then offline.html, for
 *    same-scope navigations when the network fails or errors (hash routing
 *    means one document serves all routes).
 *  - Never cache cross-origin (OCR models, cloud sync endpoints), never
 *    cache build-info.json (provenance must reflect the live deploy).
 */

const VERSION = "__SW_REVISION__";
const PRECACHE = "koodo-precache-" + VERSION;
const PRECACHE_PREFIX = "koodo-precache-";
const RUNTIME = "koodo-runtime"; // unversioned: survives redeploys
const LEGACY_RUNTIME_PREFIX = "koodo-runtime-"; // old versioned scheme, purged
const OFFLINE_URL = "./offline.html";
const PWA_SCOPE_PREFIX = "__SW_SCOPE_PREFIX__"; // e.g. "/koodo-reader/"
const CACHED_AT_HEADER = "x-koodo-cached-at";
const MAX_RUNTIME_ENTRIES = 400;
const TRIM_TO_ENTRIES = 350;

// Substituted at build time: JSON array of scope-relative URLs.
const PRECACHE_URLS = __PRECACHE_URLS__;

// Vite emits ./static/* with content hashes in the file name: the same URL
// always means the same bytes, so entries can be copied between revisions.
const isImmutableAsset = (url) => url.startsWith("./static/");

const stampResponse = (response) => {
  const headers = new Headers(response.headers);
  headers.set(CACHED_AT_HEADER, String(Date.now()));
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
};

const trimRuntimeCache = async () => {
  const cache = await caches.open(RUNTIME);
  const keys = await cache.keys();
  if (keys.length <= MAX_RUNTIME_ENTRIES) return;
  const entries = await Promise.all(
    keys.map(async (request) => {
      const response = await cache.match(request);
      const raw = response && response.headers.get(CACHED_AT_HEADER);
      const at = raw ? Number.parseInt(raw, 10) || 0 : 0;
      return { request, at };
    })
  );
  entries.sort((a, b) => a.at - b.at); // oldest first
  const excess = entries.length - TRIM_TO_ENTRIES;
  await Promise.all(
    entries.slice(0, excess).map((entry) => cache.delete(entry.request))
  );
};

// Ordered lookup: current precache, then runtime, then any cache (the one
// kept previous generation). Plain caches.match() alone would return the
// OLDEST generation's copy of a same-URL asset.
const matchInOrder = async (request) => {
  const precache = await caches.open(PRECACHE);
  const precacheHit = await precache.match(request);
  if (precacheHit) return precacheHit;
  const runtime = await caches.open(RUNTIME);
  const runtimeHit = await runtime.match(request);
  if (runtimeHit) return runtimeHit;
  return await caches.match(request);
};

const putInRuntime = async (request, response) => {
  try {
    const cache = await caches.open(RUNTIME);
    // Response bodies are single-use; stamp a clone, keep the original.
    await cache.put(request, stampResponse(response.clone()));
    await trimRuntimeCache();
  } catch (error) {
    // Cache full / storage pressure: serve the response anyway.
  }
};

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      // Previous precache generations, used to copy unchanged static assets
      // forward instead of re-downloading the whole app shell every deploy.
      const oldNames = (await caches.keys()).filter(
        (name) => name.startsWith(PRECACHE_PREFIX) && name !== PRECACHE
      );
      const oldCaches = await Promise.all(oldNames.map((n) => caches.open(n)));
      // Strict install: every entry must land (one retry each). A partial
      // precache would silently degrade offline mode; a discarded install
      // keeps the previous SW serving and the browser retries later.
      await Promise.all(
        PRECACHE_URLS.map(async (url) => {
          if (isImmutableAsset(url)) {
            for (const old of oldCaches) {
              const hit = await old.match(url);
              if (hit) {
                await cache.put(url, hit);
                return;
              }
            }
          }
          try {
            await cache.add(new Request(url, { cache: "reload" }));
          } catch (error) {
            await cache.add(new Request(url, { cache: "reload" }));
          }
        })
      );
      await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      if (self.registration.navigationPreload) {
        try {
          await self.registration.navigationPreload.disable();
        } catch (error) {
          /* older browsers */
        }
      }
      // Generation rotation, synchronous (no setTimeout: an idle-terminated
      // SW would never run it). caches.keys() is insertion-ordered, so the
      // LAST superseded precache is the previous deploy - keep exactly that
      // one for tabs still running old documents; delete everything older
      // plus every legacy versioned runtime cache (their contents are
      // either precached per generation or re-fetchable on demand).
      const names = await caches.keys();
      const oldPrecaches = names.filter(
        (name) => name.startsWith(PRECACHE_PREFIX) && name !== PRECACHE
      );
      const keepPrevious = oldPrecaches[oldPrecaches.length - 1];
      await Promise.all(
        names.map((name) => {
          const stalePrecache =
            name.startsWith(PRECACHE_PREFIX) &&
            name !== PRECACHE &&
            name !== keepPrevious;
          const legacyRuntime = name.startsWith(LEGACY_RUNTIME_PREFIX);
          return stalePrecache || legacyRuntime
            ? caches.delete(name)
            : Promise.resolve();
        })
      );
      await trimRuntimeCache();
      await self.clients.claim();
    })()
  );
});

const isSameOrigin = (url) => url.origin === self.location.origin;

// Scope-relative path prefix check: URL must live inside the PWA scope
// (Pages serves the app under /koodo-reader/).
const inScope = (url) =>
  isSameOrigin(url) && url.pathname.startsWith(PWA_SCOPE_PREFIX);

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (!inScope(url)) return; // cross-origin (OCR models, sync endpoints)

  // Provenance file: always pass through to the network.
  if (url.pathname.endsWith("/build-info.json")) return;

  // App document navigations: network-first with cached-shell fallback.
  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        let response = null;
        try {
          response = await fetch(request);
        } catch (error) {
          response = null;
        }
        if (response && response.ok) return response;
        const cache = await caches.open(PRECACHE);
        const cached =
          (await cache.match("./index.html")) ||
          (await cache.match("./")) ||
          (await caches.match(OFFLINE_URL));
        if (cached) return cached;
        return (
          response ||
          new Response("Offline", {
            status: 503,
            headers: { "Content-Type": "text/plain" },
          })
        );
      })()
    );
    return;
  }

  // Mutable vendored assets (pdf.js API+worker, wasm, cmaps, tesseract):
  // network-first so bytes always match the current deploy; the runtime
  // cache (and the current precache, which holds the index-referenced lib
  // scripts) is the offline fallback.
  if (url.pathname.startsWith(PWA_SCOPE_PREFIX + "lib/")) {
    event.respondWith(
      (async () => {
        let response = null;
        try {
          response = await fetch(request);
        } catch (error) {
          response = null;
        }
        if (response && response.status === 200) {
          await putInRuntime(request, response);
          return response;
        }
        const cached = await matchInOrder(request);
        if (cached) return cached;
        if (response) return response;
        throw new Error("offline and not cached: " + url.pathname);
      })()
    );
    return;
  }

  // Everything else in scope (content-hashed ./static/*, root files):
  // cache-first in generation order, populate the runtime cache on miss.
  event.respondWith(
    (async () => {
      const cached = await matchInOrder(request);
      if (cached) return cached;
      const response = await fetch(request);
      if (response && response.status === 200) {
        await putInRuntime(request, response);
      }
      return response;
    })()
  );
});

// Escape hatch so a page can force an update without waiting for the next
// navigation (nothing else in the app talks to the SW right now).
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});
